import json, os, re
from collections import Counter

base = ".state/sessions/history"
ref_time = os.path.getmtime("agents/optimizer/workspace/finding-cost-scan-0323-0009.md")
cat_commands = Counter()

for sid in os.listdir(base):
    meta_path = os.path.join(base, sid, "meta.json")
    session_path = os.path.join(base, sid, "session.jsonl")
    if not os.path.exists(meta_path) or not os.path.exists(session_path):
        continue
    if os.path.getmtime(meta_path) <= ref_time:
        continue
    with open(meta_path) as f:
        meta = json.load(f)
    if meta.get("agent") != "coach":
        continue

    with open(session_path) as f:
        for line in f:
            try:
                d = json.loads(line)
                if d.get("role") != "assistant":
                    continue
                content = d.get("content", [])
                if not isinstance(content, list):
                    continue
                for item in content:
                    if not isinstance(item, dict) or item.get("type") != "toolCall":
                        continue
                    if item.get("name") == "bash":
                        cmd = item.get("arguments", {}).get("command", "")
                        if re.match(r"^(cat|head|tail)\s+[\w./_-]+\s*$", cmd.strip()):
                            cat_commands[cmd.strip()] += 1
            except:
                pass

print("Coach bash-as-cat commands:")
for cmd, count in cat_commands.most_common(20):
    print(f"  {count:>3}x  {cmd}")
